const cash=(v,n='Số tiền')=>{v=Number(v);if(!Number.isInteger(v)||v<0||v>1e9)throw fail(n+' phải là số nguyên VND hợp lệ');return v};
function tx(db,fn){db.exec('BEGIN IMMEDIATE');try{const value=fn();db.exec('COMMIT');return value}catch(e){db.exec('ROLLBACK');throw e}}
function seed(db){const run=()=>tx(db,()=>{db.exec("INSERT INTO stores(id,name) VALUES(1,'Cửa hàng Trung Tâm'),(2,'Cửa hàng Riverside')");const us=[['Chủ hệ thống','owner@demo.local','owner',null],['Quản lý Trung Tâm','manager1@demo.local','manager',1],['Thu ngân An','cashier1@demo.local','cashier',1],['Thu ngân Bình','cashier2@demo.local','cashier',1],['Kho Chi','stock1@demo.local','inventory',1],['Quản lý Riverside','manager2@demo.local','manager',2],['Thu ngân Dũng','cashier3@demo.local','cashier',2],['Thu ngân Em','cashier4@demo.local','cashier',2],['Kho Giang','stock2@demo.local','inventory',2],['Nhân viên Hạnh','staff@demo.local','cashier',2]];let q=db.prepare('INSERT INTO users(name,email,password_hash,role,store_id)VALUES(?,?,?,?,?)');us.forEach(x=>q.run(x[0],x[1],hash('Demo@123'),x[2],x[3]));[['Đồ uống',1],['Món ăn',1],['Hàng bán lẻ',1],['Đồ uống',2],['Món ăn',2],['Hàng bán lẻ',2]].forEach(x=>db.prepare('INSERT INTO categories(name,store_id)VALUES(?,?)').run(...x));const ps=[['Cà phê sữa','TT-CF01',32000,1,1,80],['Trà đào','TT-TR01',39000,1,1,60],['Cơm gà','TT-FO01',65000,2,1,35],['Bánh mì bò','TT-FO02',48000,2,1,30],['Cà phê hạt 250g','TT-RT01',145000,3,1,20],['Nước suối','TT-RT02',15000,3,1,100],['Cold brew','RV-CF01',45000,4,2,50],['Trà sữa','RV-TR01',42000,4,2,55],['Mì Ý bò bằm','RV-FO01',89000,5,2,25],['Salad gà','RV-FO02',72000,5,2,25],['Bình giữ nhiệt','RV-RT01',220000,6,2,15],['Cookie hộp','RV-RT02',95000,6,2,30]];ps.forEach(x=>{let r=db.prepare('INSERT INTO products(name,sku,price,category_id,store_id)VALUES(?,?,?,?,?)').run(...x.slice(0,5));db.prepare('INSERT INTO inventory VALUES(?,?)').run(Number(r.lastInsertRowid),x[5])});db.exec("INSERT INTO customers(name,phone,email,note,store_id)VALUES('Khách mẫu An','0900000001','an@example.test','Dữ liệu minh họa',1),('Khách mẫu Bình','0900000002','binh@example.test','Dữ liệu minh họa',2)")});run()}
function open(file){fs.mkdirSync(path.dirname(file),{recursive:true});const db=new DatabaseSync(file);db.exec("PRAGMA foreign_keys=ON;PRAGMA journal_mode=WAL;PRAGMA busy_timeout=5000;CREATE TABLE IF NOT EXISTS stores(id INTEGER PRIMARY KEY,name TEXT NOT NULL);CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','manager','cashier','inventory')),store_id INTEGER REFERENCES stores(id),active INTEGER NOT NULL DEFAULT 1);CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL,store_id INTEGER REFERENCES stores(id),UNIQUE(name,store_id));CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,sku TEXT UNIQUE NOT NULL,price INTEGER NOT NULL CHECK(price>=0),category_id INTEGER REFERENCES categories(id),store_id INTEGER REFERENCES stores(id),active INTEGER NOT NULL DEFAULT 1);CREATE TABLE IF NOT EXISTS inventory(product_id INTEGER PRIMARY KEY REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>=0));CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,phone TEXT,email TEXT,note TEXT,store_id INTEGER REFERENCES stores(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,code TEXT UNIQUE,store_id INTEGER REFERENCES stores(id),customer_id INTEGER REFERENCES customers(id),subtotal INTEGER,total INTEGER,status TEXT DEFAULT 'paid',payment_method TEXT,idem_key TEXT,created_by INTEGER REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(created_by,idem_key));CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),product_id INTEGER REFERENCES products(id),product_name TEXT,unit_price INTEGER,quantity INTEGER,line_total INTEGER);CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),method TEXT,amount INTEGER,reference TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS stock_ledger(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id),store_id INTEGER REFERENCES stores(id),change_qty INTEGER,balance_after INTEGER,reason TEXT,order_id INTEGER,created_by INTEGER REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP)");migrate(db);if(!db.prepare('SELECT count(*) n FROM stores').get().n)seed(db);return db}
