if(m==='GET'&&!url.pathname.startsWith('/api/')){let f=url.pathname==='/'?'index.html':decodeURIComponent(url.pathname.slice(1));if(f.includes('..')||path.isAbsolute(f))throw fail('Sai đường dẫn');f=path.join(pub,f);if(!fs.existsSync(f)){res.writeHead(404);return res.end()}let type=f.endsWith('.css')?'text/css':f.endsWith('.js')?'text/javascript':'text/html';res.writeHead(200,{...securityHeaders,'content-type':type+'; charset=utf-8','cache-control':f.endsWith('.html')?'no-store':'public, max-age=300'});return res.end(fs.readFileSync(f))}
